#include <stdlib.h>
#include <string.h>

// Define the git_pkt structure
typedef struct {
    char *ref;
    char *msg;
} git_pkt;

typedef struct {
    git_pkt base;
    // Additional fields can be added here if needed
} git_pkt_ng;

int parse_pkt_git_pkt(char **out, const char *line, size_t len) {
    // Validate inputs
    if (!out || !line || len == 0) {
        return -1;
    }

    // Allocate memory for the git_pkt_ng structure
    git_pkt_ng *pkt = (git_pkt_ng *)malloc(sizeof(git_pkt_ng));
    if (!pkt) {
        return -1;
    }

    // Initialize fields to NULL to ensure proper cleanup
    pkt->base.ref = NULL;
    pkt->base.msg = NULL;

    // Find the separator between ref and msg
    const char *sep = memchr(line, '\0', len);
    if (!sep) {
        free(pkt);
        return -1;
    }

    // Calculate lengths of ref and msg
    size_t ref_len = sep - line;
    size_t msg_len = len - (sep + 1 - line);

    // Allocate and copy ref
    pkt->base.ref = (char *)malloc(ref_len + 1);
    if (!pkt->base.ref) {
        free(pkt);
        return -1;
    }
    memcpy(pkt->base.ref, line, ref_len);
    pkt->base.ref[ref_len] = '\0';

    // Allocate and copy msg
    pkt->base.msg = (char *)malloc(msg_len + 1);
    if (!pkt->base.msg) {
        free(pkt->base.ref);
        free(pkt);
        return -1;
    }
    memcpy(pkt->base.msg, sep + 1, msg_len);
    pkt->base.msg[msg_len] = '\0';

    // Assign the output pointer
    *out = (char *)pkt;

    return 0;
}
